<svg xmlns="http://www.w3.org/2000/svg" xmlns:scada="http://cube-scada.io/ns/v1" viewBox="0 0 100 100" width="100" height="100">
  <metadata>
    <scada:element>
      <scada:meta type="signal-meter" label="&#x4FE1;&#x53F7;&#x91CF;&#x4EEA;&#x8868;" category="industrial" version="1.0.0"/>
      <scada:props>
        <scada:prop name="signalLevel" type="number" label="&#x4FE1;&#x53F7;&#x5F3A;&#x5EA6;" default="60" min="0" max="100" unit="%" domain="observe" semantic="status.value" required="false" bindable="true" controllable="false"/>
        <scada:prop name="alarm" type="boolean" label="&#x544A;&#x8B66;&#x72B6;&#x6001;" default="false" domain="observe" semantic="status.state" required="false" bindable="true" controllable="false"/>
        <scada:prop name="bodyColor" type="color" label="&#x9762;&#x677F;&#x989C;&#x8272;" default="#f8fafc" domain="observe" semantic="style.bodyColor" required="false" bindable="true" controllable="false"/>
      </scada:props>
      <scada:mappings>
        <scada:map prop="bodyColor" selector="#panel" attr="fill"/>
        <scada:map prop="signalLevel" selector="#value-text" attr="textContent" transform="String(Math.round(value ?? 0)) + '%'"/>
        <scada:map prop="signalLevel" selector="#bar-1" attr="opacity" transform="Number(value ?? 0) >= 20 ? '1' : '0.2'"/>
        <scada:map prop="signalLevel" selector="#bar-2" attr="opacity" transform="Number(value ?? 0) >= 40 ? '1' : '0.2'"/>
        <scada:map prop="signalLevel" selector="#bar-3" attr="opacity" transform="Number(value ?? 0) >= 60 ? '1' : '0.2'"/>
        <scada:map prop="signalLevel" selector="#bar-4" attr="opacity" transform="Number(value ?? 0) >= 80 ? '1' : '0.2'"/>
        <scada:map prop="alarm" selector="#status-lamp" attr="fill" transform="value ? '#ef4444' : '#22c55e'"/>
      </scada:mappings>
      <scada:animations>
        <scada:animation id="signal-alarm-pulse" triggerProp="alarm" triggerCondition="value === true" target="#status-lamp" keyframes='[{"opacity":1},{"opacity":0.35},{"opacity":1}]' duration="900" iterations="Infinity" easing="ease-in-out"/>
      </scada:animations>
    </scada:element>
  </metadata>

  <rect id="panel" x="8" y="8" width="84" height="84" rx="12" fill="#f8fafc" stroke="#334155" stroke-width="2"/>
  <text x="50" y="22" text-anchor="middle" font-size="11" fill="#0f172a">&#x4FE1;&#x53F7;&#x91CF;</text>

  <rect id="bar-1" x="26" y="58" width="8" height="8" rx="2" fill="#22c55e"/>
  <rect id="bar-2" x="38" y="50" width="8" height="16" rx="2" fill="#22c55e"/>
  <rect id="bar-3" x="50" y="42" width="8" height="24" rx="2" fill="#22c55e"/>
  <rect id="bar-4" x="62" y="34" width="8" height="32" rx="2" fill="#22c55e"/>

  <text id="value-text" x="50" y="78" text-anchor="middle" font-size="12" fill="#0f172a">60%</text>
  <circle id="status-lamp" cx="82" cy="18" r="5" fill="#22c55e" stroke="#14532d" stroke-width="1"/>
</svg>
